Q: How can I allow pointer events beneath an element that needs to detect mouse hover? (dHTML) A: <p>Just set <code>.sidebar</code> <code>z-index</code> in hidden state smaller than <code>z-index</code> of the elements that overlap it.
<div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// the hidden sidebar detecting mouse movements
let hiddenSidebarDiv = document.querySelector("[data-js-tag='hidden-sidebar']");

// the button that should bring back the sidebar when pressed
let showSidebarButton = document.querySelector("[data-js-tag='show-sidebar-button']");

let moveButton = (mousePosition = {x: 0, y: 0}) =&gt; {
  showSidebarButton.style.top = `${mousePosition.y}px`;
}

hiddenSidebarDiv.addEventListener("mouseenter", (event) =&gt; {
  if(hiddenSidebarDiv.classList.contains('hide')){
    showSidebarButton.classList.add("active");
    moveButton({x: event.x, y: event.y});
  }
});

showSidebarButton.addEventListener("click", (event) =&gt; {
    hiddenSidebarDiv.classList.remove("hide");
    showSidebarButton.classList.remove("active");
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>body{
  padding: 25px;
  background-color: #32442e;
  padding: 0;
}
.title {
    color: #a2a323;
    position:relative;
    z-index:1;
}
button {
    color: #a2a323;
    background-color: #12141e;
    position:relative;
    z-index:1;
}

.hidden-sidebar{
  position: fixed;
  background-color: green;
  width: 100px;
  inset: 0 auto 0 0;
  z-index: 6;
  &amp;.hide {
    background-color: #03030313;
    z-index: 0;
  }
}

.show-sidebar-button{
  position: fixed;
  z-index: 9;
  left: 0;
  display:none;
  &amp;.active{
    display:block;
  }
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;h1 class="title"&gt;Some content&lt;/h1&gt;
&lt;button data-js-tag="detect-button-press"&gt;a button that should be pressable even with the hidden sidebar above it&lt;/button&gt;
&lt;div data-js-tag="hidden-sidebar" class="hidden-sidebar hide"&gt;&lt;/div&gt;
&lt;button data-js-tag="show-sidebar-button" type="submit" class="hide show-sidebar-button"&gt;bring sidebar back&lt;/button&gt;</code></pre>
